#!/usr/bin/env ts-node
// SCS-001 Block A — Trend Agent Runner
// Usage: npx ts-node scripts/scs001/run-trend-agent.ts [--feed <path>] [--dry-run]

import { TrendAgent, saveBatch } from '../../agents/scs001-trend/index';
import { join } from 'path';

const args = process.argv.slice(2);
const getArg = (flag: string, def: string): string => {
  const i = args.indexOf(flag);
  return i !== -1 && args[i + 1] ? args[i + 1] : def;
};

const FEED_PATH = getArg('--feed', '');
const DRY_RUN  = args.includes('--dry-run');
const ROOT     = join(__dirname, '..', '..');
const OUT_DIR  = join(ROOT, 'workspace', 'scs001', 'trend-outputs');

async function main(): Promise<void> {
  console.log('\n🔭 SCS-001 Trend Agent — Starting...');
  console.log(`Feed: ${FEED_PATH || 'mock (default)'}`);
  console.log(`Dry run: ${DRY_RUN}\n`);

  const agent = new TrendAgent(FEED_PATH || undefined);
  const batch = agent.run();

  console.log(`\n📊 Batch: ${batch.batch_id}`);
  console.log(`Status: ${batch.oracle6_feed_status}`);
  console.log(`Topics qualified: ${batch.topics.length}`);
  batch.topics.forEach(t => {
    console.log(`  [${t.confidence_score}] ${t.topic_name}`);
  });

  if (!DRY_RUN) {
    const outPath = saveBatch(batch, OUT_DIR);
    console.log(`\n✅ Saved → ${outPath}`);
  } else {
    console.log('\n[DRY RUN] Output not saved.');
  }
}

main().catch(err => { console.error('Trend Agent failed:', err); process.exit(1); });
