#!/usr/bin/env ts-node
// SCS-001 Block A — Trend Agent Contract Compliance Test
// Validates TrendingTopicBatch against trending-topic-v1.json required fields

import { TrendAgent } from '../../agents/scs001-trend/index';

function assert(condition: boolean, msg: string): void {
  if (!condition) { console.error(`  ✗ FAIL: ${msg}`); process.exitCode = 1; }
  else { console.log(`  ✓ PASS: ${msg}`); }
}

async function main(): Promise<void> {
  console.log('\n🧪 SCS-001 Trend Agent — Contract Compliance Test\n');
  const agent = new TrendAgent();
  const batch = agent.run();

  // Batch-level checks
  assert(typeof batch.batch_id === 'string' && batch.batch_id.startsWith('trend-batch-'), 'batch_id format valid');
  assert(typeof batch.generated_at === 'string', 'generated_at present');
  assert(['mock', 'live', 'degraded'].includes(batch.oracle6_feed_status), 'oracle6_feed_status valid enum');
  assert(Array.isArray(batch.topics), 'topics is array');
  assert(batch.topics.length >= 3, `At least 3 topics qualified (got ${batch.topics.length})`);
  assert(batch.topics.length === 5, `All 5 mock signals qualified at gate=60 (got ${batch.topics.length})`);

  // Sort order check
  for (let i = 1; i < batch.topics.length; i++) {
    assert(
      batch.topics[i].confidence_score <= batch.topics[i - 1].confidence_score,
      `Topics sorted by confidence desc (idx ${i-1}:${batch.topics[i-1].confidence_score} >= idx ${i}:${batch.topics[i].confidence_score})`
    );
  }

  // Per-topic checks
  batch.topics.forEach((t, idx) => {
    assert(typeof t.topic_id === 'string' && t.topic_id.length > 0, `topic[${idx}] topic_id present`);
    assert(typeof t.topic_name === 'string' && t.topic_name.length > 0, `topic[${idx}] topic_name present`);
    assert(typeof t.confidence_score === 'number' && t.confidence_score >= 60, `topic[${idx}] confidence_score >= 60`);
    assert(Array.isArray(t.keyword_cluster) && t.keyword_cluster.length >= 3, `topic[${idx}] keyword_cluster >= 3 items`);
    assert(Array.isArray(t.domain_tags) && t.domain_tags.length >= 1, `topic[${idx}] domain_tags present`);
  });

  const code = process.exitCode === 1 ? 1 : 0;
  console.log(`\n${code === 0 ? '✅ All checks passed' : '❌ Some checks failed'}`);
  process.exit(code);
}

main().catch(err => { console.error('Validation failed:', err); process.exit(1); });
```

